/// <summary>
/// Creates NDX_CentralStoreDistributionLine record
/// </summary>
/// <param name = "_nDX_CentralStoreDistributionLine">NDX_CentralStoreDistributionLine record</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>NDX_CentralStoreDistributionLine record</returns>
server static public NDX_CentralStoreDistributionLine create(NDX_CentralStoreDistributionLine _nDX_CentralStoreDistributionLine, boolean _forUpdate = false)
{
    NDX_CentralStoreDistributionLine      nDX_CentralStoreDistributionLine;

    if (_forUpdate)
    {
        nDX_CentralStoreDistributionLine.selectForUpdate(_forUpdate);
    }
    nDX_CentralStoreDistributionLine.initValue();
    nDX_CentralStoreDistributionLine.CSDId              = _nDX_CentralStoreDistributionLine.CSDId;
    nDX_CentralStoreDistributionLine.smmSalesDistrictId    = _nDX_CentralStoreDistributionLine.smmSalesDistrictId;
    nDX_CentralStoreDistributionLine.CustAccount        = _nDX_CentralStoreDistributionLine.CustAccount;

    return nDX_CentralStoreDistributionLine;
}

/// <summary>
/// finds or creates NDX_CentralStoreDistributionLine record
/// </summary>
/// <param name = "_NDX_CentralStoreDistributionLine">NDX_CentralStoreDistributionLine orig records</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>NDX_CentralStoreDistributionLine record</returns>
client server static public NDX_CentralStoreDistributionLine findOrCreate(NDX_CentralStoreDistributionLine _NDX_CentralStoreDistributionLine, boolean _forUpdate = false)
{
    NDX_CentralStoreDistributionLine  nDX_CentralStoreDistributionLine;
    nDX_CentralStoreDistributionLine = NDX_CentralStoreDistributionLine::findCS(_NDX_CentralStoreDistributionLine, _forUpdate);

    if (!nDX_CentralStoreDistributionLine)
    {
        nDX_CentralStoreDistributionLine = NDX_CentralStoreDistributionLine::create(_NDX_CentralStoreDistributionLine, _forUpdate);
    }
    return nDX_CentralStoreDistributionLine;
}

/// <summary>
/// finds NDX_CentralStoreDistributionLine record
/// </summary>
/// <param name = "_nDX_CentralStoreDistributionLine">NDX_CentralStoreDistributionLine record</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>NDX_CentralStoreDistributionLine record</returns>
client server static public NDX_CentralStoreDistributionLine findCS(NDX_CentralStoreDistributionLine _nDX_CentralStoreDistributionLine, boolean _forUpdate = false)
{
    NDX_CentralStoreDistributionLine      nDX_CentralStoreDistributionLine;
    ;
    if (_forUpdate)
    {
        nDX_CentralStoreDistributionLine.selectForUpdate(_forUpdate);
    }

    select firstOnly nDX_CentralStoreDistributionLine
        where nDX_CentralStoreDistributionLine.CSDId == _nDX_CentralStoreDistributionLine.CSDId
           && nDX_CentralStoreDistributionLine.smmSalesDistrictId == _nDX_CentralStoreDistributionLine.smmSalesDistrictId
           && nDX_CentralStoreDistributionLine.CustAccount == _nDX_CentralStoreDistributionLine.CustAccount;

    return nDX_CentralStoreDistributionLine;
}

/// <summary>
/// Display customer name
/// </summary>
/// <returns>Name</returns>
[SysClientCacheDataMethod(true)]
display Name dispCustName()
{
    return CustTable::find(this.CustAccount).nameAlias();
}

/// <summary>
/// diplays sales district name
/// </summary>
/// <returns>Name</returns>
[SysClientCacheDataMethod(true)]
display smmSalesDistrictDescription dispSalesDistrictName()
{
    return smmBusRelSalesDistrictGroup::avaFind(this.smmSalesDistrictId).Description;
}
